#define CUI_EFFECTS_IMPLEMENTATION
#include "cui_effects.h"
#include <stdio.h>
static float source_width(float x,float w,float offset,float spread) {
    float origin=(x+offset)-spread;
    float size=w+(spread+spread);
    float near=floorf(origin),far=fmaxf(near,ceilf(origin+size));
    return far-near;
}
int main(void) {
    const float xs[]={0,.1f,1.25f,16384,4000.1f,-16384};
    const float ws[]={0,.0001f,.01f,.2f,1.0001f,32};
    const float ss[]={0,.0001f,.001f,.01f,.1f,.6f,-.6f,-.5001f,-.001f};
    const float os[]={0,.001f,1.5f,4096,-4096};
    unsigned printed=0,geometry=0,collapsed=0;
    for(unsigned ix=0;ix<6;ix++)for(unsigned iw=0;iw<6;iw++)for(unsigned is=0;is<9;is++)for(unsigned io=0;io<5;io++) {
        cui_drop_shadow_paint p={.caster={xs[ix],20.25f,ws[iw],4},.layer={.offset_x=os[io],.spread=ss[is],.color={0,0,0,255}}};
        cui_drop_shadow_raster q;
        if(!cui_effect_drop_shadow_query(p,1,0,0,&q))return 2;
        float expected=source_width(p.caster.x,p.caster.w,p.layer.offset_x,p.layer.spread);
        if(expected!=q.covered_layer.w) {
            bool empty=p.caster.w==0||p.caster.w+2*p.layer.spread<=0;
            if(empty)collapsed++;else geometry++;
            if(printed<12 && !empty){printf("positive_geometry x=%.9g w=%.9g offset=%.9g spread=%.9g source=%.9g cui=%.9g\n",p.caster.x,p.caster.w,p.layer.offset_x,p.layer.spread,expected,q.covered_layer.w);printed++;}
        }
    }
    cui_drop_shadow_paint p={.caster={20.25f,20.25f,1,1},.layer={.spread=-.6f,.color={0,0,0,255}}};
    cui_drop_shadow_raster q;
    if(!cui_effect_drop_shadow_query(p,1,0,0,&q))return 3;
    printf("fractional_collapse source=%.9g cui=%u\n",source_width(p.caster.x,p.caster.w,0,p.layer.spread),q.width);
    printf("mismatched_cases positive=%u collapsed=%u\n",geometry,collapsed);
    return 0;
}
